import{_ as i,l,o as t,c as s,v as e,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"指称语义直觉","description":"","frontmatter":{"title":"指称语义直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/denotational-semantics.md","filePath":"cs/denotational-semantics.md","lastUpdated":1789023840000}'),m={name:"cs/denotational-semantics.md"};function h(k,a,_,b,u,f){const o=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="指称语义直觉" tabindex="-1">指称语义直觉 <a class="header-anchor" href="#指称语义直觉" aria-label="Permalink to &quot;指称语义直觉&quot;">​</a></h1><div class="epigraph"><p>把项映射到数学对象：函数、域上的点、关系。组合性：复合项的含义由部件的含义算出。操作语义给步骤，指称给「是什么」。</p><footer>—— 据 Scott 域论；Stoy, Denotational Semantics；Pierce TAPL 短论；Knaster–Tarski 课的延续整理</footer></div><p>上一课<a href="/cs/operational-semantics">操作语义</a>给出 \\(\\to\\)。缺口是<strong>指称</strong>：\\(\\llbracket t\\rrbracket\\) 是集合论或域里的元素，β 在指称里变成等式。递归要用最小不动点——<a href="/cs/knaster-tarski-fixpoint">Knaster–Tarski</a> 已给格上的工具。本课直觉：为何需要域（不终止），不把完整域论作业写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>操作语义的「等价」是互模拟或上下文等价，难算。指称：两个项含义相同则应可替换（组合性保证合同）。缺口是<strong>含义函数</strong>，不是再列 SOS 规则。</p><p>不终止：朴素函数集没有 \\(\\bot\\)。Scott：偏序、连续函数，\\(Y\\) 是最小不动点。STLC 无递归则可用完全的集合论函数。</p><h3 id="指称不是「编译到数学的编译器」" tabindex="-1">指称不是「编译到数学的编译器」 <a class="header-anchor" href="#指称不是「编译到数学的编译器」" aria-label="Permalink to &quot;指称不是「编译到数学的编译器」&quot;">​</a></h3><p>它是规范。编译器正确性：\\(\\llbracket\\mathrm{target}\\rrbracket\\) 与 \\(\\llbracket\\mathrm{source}\\rrbracket\\) 相关（后课 CompCert 用操作+模拟更多）。不要把指称当运行时。</p><p><span class="marginnote">Dana Scott。Stoy 的教材。Plotkin 的 ADEQUACY：指称与操作一致。本课不写幂域处理非确定的全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>STLC：\\(\\llbracket\\tau\\to\\tau&#39;\\rrbracket=\\llbracket\\tau\\rrbracket\\to\\llbracket\\tau&#39;\\rrbracket\\)，\\(\\llbracket\\lambda x.t\\rrbracket\\) 是函数。带递归：在域上取 \\(\\mathrm{fix}\\)。命令式：状态变换器 \\(\\mathrm{State}\\to\\mathrm{State}\\times\\mathrm{Val}\\)，或用单子。</p>',11)),(t(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A1%B9%22%5D%20--%3E%20D%5B%22%E2%9F%A6t%E2%9F%A7%20%E6%95%B0%E5%AD%A6%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20OP%5B%22%E6%93%8D%E4%BD%9C%20%E2%86%92*%20v%22%5D%20--%3E%20ADQ%5B%22adequacy%22%5D%0A%20%20D%20--%3E%20ADQ%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与类型：含义可只给良型项定义，健全性变成「含义有定义」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完全抽象：指称相等 iff 上下文等价。PPL 里往往失败（序列化、并行），需精细模型。本课只要知道这是理想，不是免费定理。</p><p>不要用指称去「优化浮点」而不谈 IEEE——指称必须先选数学模型，fast-math 后课会破坏它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Scott 定理。后课默认：含义可组合；递归靠不动点。下一课抽象解释：在格上近似指称/收集语义，服务分析。</p><p>也不把 UML 当指称语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指称：项 → 数学对象，求组合性。</li><li>不终止与递归需要域与最小不动点。</li><li>adequacy 把指称和操作对齐。</li><li>出处：Scott；Stoy；对照 Plotkin、Pierce；Knaster–Tarski。</li></ul>',9))])}const T=i(m,[["render",h]]);export{A as __pageData,T as default};
